+        let mut best = (f64::INFINITY, 0);
+        for k in 0..b.len() - 1 {
+            let c = cost(&b[k], &b[k + 1]);
+            if c < best.0 {
+                best = (c, k);
+            }
+        }
+        let k = best.1;
+        b[k] = join(&b[k], &b[k + 1]);
+        b.remove(k + 1);
+    }
+    b
+}
