+    let p = HolderProfile::envelope(&tris).expect("a sane body");
+    for k in 0..=100 {
+        let z = f64::from(k) * 0.1;
+        assert!(band_at(&p, z) >= 8.0, "z {z}: reach {}", band_at(&p, z));
+    }
+}
