+fn temp_stl(tag: &str) -> std::path::PathBuf {
+    let dir = std::env::temp_dir().join(format!("cc-371-ui-{}-{tag}", std::process::id()));
+    std::fs::create_dir_all(&dir).unwrap();
+    dir.join("holder.stl")
