+    harness.get_by_label("Fit").click();
+    harness.run();
+    let d = &harness.state().state.tool_body_ui;
+    assert_eq!((d.zoom, d.pan, d.yaw, d.pitch), (0.0, [0.0; 2], 0.0, 0.0), "Fit restores the default view");
+    let _ = std::fs::remove_dir_all(path.parent().unwrap());
+}

